import re
# parse enum values
vals={}
for line in open('arch/X86/X86GenInstrInfo.inc'):
    m=re.match(r'\s*(X86_\w+)\s*=\s*(\d+),', line)
    if m: vals[m.group(1)]=int(m.group(2))
    else:
        m=re.match(r'\s*(X86_\w+)\s*,', line)
        if m and vals:
            vals[m.group(1)]=max(vals.values())+1
# parse access entries order from MappingInsnOp.inc comments
entries=[]
lines=open('arch/X86/X86MappingInsnOp.inc').read().splitlines()
for i,l in enumerate(lines):
    m=re.search(r'/\* (X86_\w+),', l)
    if m:
        name=m.group(1); arr=''
        for j in range(i+1,min(i+6,len(lines))):
            if '{' in lines[j] and '}' in lines[j]: arr=lines[j]; break
        cnt=0; toks=[]
        if arr:
            inside=arr[arr.find('{')+1:arr.rfind('}')]
            parts=[p.strip() for p in inside.split(',')]
            for p in parts:
                if p=='0': break
                cnt+=1; toks.append(p)
        entries.append((name,cnt,toks))
short={name:(cnt,toks) for name,cnt,toks in entries if cnt<=2}
# grep comments in asmwriter listing with names from short and high operand indices preceding maybe
text=open('arch/X86/X86GenAsmWriter.inc').read().splitlines()
for idx,l in enumerate(text):
    if '//' in l:
        names=re.findall(r'\b(X86_\w+)\b', l)
        # comments omit X86_? actually e.g AESKEYGENASSIST128rm no prefix
        raw=re.findall(r'\b[A-Z][A-Z0-9_]+[A-Za-z0-9_]*\b', l.split('//',1)[1])
        cand=[]
        for r in raw:
            n='X86_'+r
            if n in short: cand.append(n)
        if cand:
            block='\n'.join(text[idx:idx+12])
            mx=max([int(x) for x in re.findall(r'printOperand\(MI, (\d+)', block)] or [-1])
            if mx>=2:
                for n in cand[:5]:
                    print(idx+1, 'maxop',mx, n, short[n], l.strip())
                print(block[:500].replace('\n',' | '))
                print('---')
